static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer keybuf, noncebuf, ptbuf, aadbuf;
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &keybuf, &noncebuf, &ptbuf, &aadbuf))
        return NULL;
    if (keybuf.len != 32 || noncebuf.len != 12) {
        PyBuffer_Release(&keybuf); PyBuffer_Release(&noncebuf);
        PyBuffer_Release(&ptbuf); PyBuffer_Release(&aadbuf);
        PyErr_SetString(PyExc_ValueError, "bad key/nonce size");
        return NULL;
    }

    Py_ssize_t n = ptbuf.len;
    PyObject *ct = PyBytes_FromStringAndSize(NULL, n);
    PyObject *tag = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct || !tag) {
        Py_XDECREF(ct); Py_XDECREF(tag);
        PyBuffer_Release(&keybuf); PyBuffer_Release(&noncebuf);
        PyBuffer_Release(&ptbuf); PyBuffer_Release(&aadbuf);
        return NULL;
    }

    int nthreads = 6;
    if (n < 1 << 20) nthreads = 1;
    Py_ssize_t block = 64;
    Py_ssize_t chunk = (n / nthreads / block) * block;
    if (chunk == 0) { nthreads = 1; chunk = n; }

    job_t jobs[16];
    pthread_t threads[16];
    int actual = 0;
    Py_ssize_t off = 0;
    unsigned int base_counter = 1;
    while (off < n && actual < 16) {
        Py_ssize_t sz = (actual == nthreads - 1) ? (n - off) : chunk;
        if (sz > n - off) sz = n - off;
        job_t *j = &jobs[actual];
        j->out = (unsigned char *)PyBytes_AS_STRING(ct) + off;
        j->in = (const unsigned char *)ptbuf.buf + off;
        j->len = (size_t)sz;
        memcpy(j->key, keybuf.buf, 32);
        j->counter[0] = base_counter;
        memcpy(&j->counter[1], noncebuf.buf, 12);
        base_counter += (unsigned int)((sz + 63) / 64);
        off += sz;
        actual++;
        if (off >= n) break;
    }

    Py_BEGIN_ALLOW_THREADS
    for (int i = 0; i < actual; i++)
        pthread_create(&threads[i], NULL, worker, &jobs[i]);
    for (int i = 0; i < actual; i++)
        pthread_join(threads[i], NULL);
    Py_END_ALLOW_THREADS

    /* Poly1305 tag computed in Python side; return ciphertext only here */
    PyBuffer_Release(&keybuf); PyBuffer_Release(&noncebuf);
    PyBuffer_Release(&ptbuf); PyBuffer_Release(&aadbuf);
    Py_DECREF(tag);
    return ct;
}

